{
  "title": "Systematic Review of the Accuracy of Large Language Models for Title and Abstract Screening Compared with Human Reviewers",
  "research_question": "How accurate are large language models at title and abstract screening for systematic reviews, compared with human reviewers?",
  "rationale": "Automated screening promises to reduce workload in systematic reviews, yet the performance of large language models (LLMs) for title and abstract screening remains uncertain. Existing studies report heterogeneous accuracy metrics and methodological quality, making it difficult for reviewers to adopt LLMs confidently. A systematic synthesis of comparative evidence will clarify the current state of LLM screening performance and identify gaps for future research.",
  "objectives": [
    "To identify and summarise primary research that evaluates the performance of LLMs for title and abstract screening in systematic reviews.",
    "To compare LLM screening accuracy with that of human reviewers using standard performance measures (e.g., sensitivity, specificity, precision, recall, F1).",
    "To assess the methodological quality of included studies and explore factors influencing LLM performance."
  ],
  "framework": "PICO",
  "framework_elements": {
    "Population": "Records (titles and abstracts) retrieved for systematic review screening",
    "Intervention": "Screening performed by a large language model (e.g., GPT‑4, Claude, LLaMA)",
    "Comparator": "Screening performed by human reviewers (single or dual independent screening)",
    "Outcome": "Accuracy metrics of screening decisions (sensitivity, specificity, precision, recall, F1, area under the ROC curve)"
  },
  "inclusion_criteria": [
    {
      "id": "I1",
      "text": "Primary research that evaluates a large language model for title and/or abstract screening of systematic review records.",
      "full_text_only": false
    },
    {
      "id": "I2",
      "text": "The study reports a quantitative comparison between the LLM and at least one human reviewer or a human reference standard.",
      "full_text_only": false
    },
    {
      "id": "I3",
      "text": "The population consists of records retrieved for any health‑related systematic review (any clinical, public‑health or health‑services topic).",
      "full_text_only": false
    },
    {
      "id": "I4",
      "text": "The article is written in English.",
      "full_text_only": false
    },
    {
      "id": "I5",
      "text": "The study provides at least one accuracy measure (e.g., sensitivity, specificity, precision, recall, F1, AUC).",
      "full_text_only": false
    },
    {
      "id": "I6",
      "text": "Full text is available for data extraction.",
      "full_text_only": true
    }
  ],
  "exclusion_criteria": [
    {
      "id": "E1",
      "text": "Not a primary research report (editorials, commentaries, letters, protocols, narrative or systematic reviews).",
      "full_text_only": false
    },
    {
      "id": "E2",
      "text": "Studies that evaluate LLMs for tasks other than title/abstract screening (e.g., full‑text retrieval, data extraction, risk‑of‑bias assessment).",
      "full_text_only": false
    },
    {
      "id": "E3",
      "text": "Studies that use only simulated data without real systematic‑review records.",
      "full_text_only": false
    },
    {
      "id": "E4",
      "text": "Conference abstracts without a full‑text manuscript.",
      "full_text_only": true
    },
    {
      "id": "E5",
      "text": "Studies that do not provide a human comparator or reference standard for screening decisions.",
      "full_text_only": true
    },
    {
      "id": "E6",
      "text": "Non‑English language publications.",
      "full_text_only": false
    }
  ],
  "study_designs": [
    "Diagnostic accuracy study",
    "Cross‑sectional comparative study",
    "Randomised controlled trial of screening methods",
    "Quasi‑experimental study"
  ],
  "date_from": null,
  "date_to": null,
  "languages": [
    "English"
  ],
  "databases": [
    "pubmed",
    "europepmc",
    "arxiv",
    "semantic_scholar"
  ],
  "outcomes": [
    "Sensitivity (recall) of LLM screening",
    "Specificity of LLM screening",
    "Precision (positive predictive value)",
    "F1 score",
    "Area under the ROC curve (AUC)",
    "Time taken for screening (if reported)"
  ],
  "data_items": [
    "Population description (type of systematic review, number of records screened)",
    "LLM model name and version",
    "Prompting / fine‑tuning strategy used",
    "Human reviewer process (single, dual, consensus)",
    "Reference standard definition (gold‑standard inclusion/exclusion decisions)",
    "Accuracy metrics reported (sensitivity, specificity, precision, recall, F1, AUC)",
    "Sample size of screened records",
    "Screening time or efficiency measures",
    "Risk‑of‑bias assessment outcome"
  ],
  "risk_of_bias_approach": "Diagnostic accuracy studies will be appraised with QUADAS‑2; non‑randomised comparative designs will be assessed using ROBINS‑I; any randomised trials of screening methods will be evaluated with RoB 2. Two reviewers will independently apply the tools, with disagreements resolved by consensus.",
  "synthesis_plan": "A narrative synthesis will summarise study characteristics, LLM configurations, and reported accuracy metrics, grouped by LLM type and screening workflow. Where at least three studies report the same metric on comparable populations, a random‑effects meta‑analysis of sensitivity and specificity will be performed using a bivariate model; otherwise, results will be presented descriptively.",
  "meta_analysis_planned": true
}

{
  "briefs": [
    {
      "stage": "search_strategy",
      "objective": "Develop a reproducible search that captures all primary studies evaluating LLMs for title/abstract screening against human reviewers.",
      "guidance": "Combine LLM names (GPT‑4, Claude, LLaMA) with screening terms (\"title screening\", \"abstract selection\"). Exclude generic AI or full‑text extraction papers. Beware synonyms like \"machine learning\" that may not refer to LLMs. Use health databases and preprint servers."
    },
    {
      "stage": "retrieval",
      "objective": "Obtain full‑text PDFs for every record retrieved by the search.",
      "guidance": "Prioritize open‑access sources; request PDFs via institutional links. Flag conference abstracts and pay‑walled items for possible exclusion. Verify that each document contains methods describing LLM screening of titles/abstracts."
    },
    {
      "stage": "title_abstract_screening",
      "objective": "Rapidly filter records to retain only studies meeting inclusion criteria.",
      "guidance": "Reject obvious non‑primary reports, editorials, or studies on full‑text tasks. Watch for ambiguous terms like \"AI screening\" that may refer to risk‑of‑bias tools. Ensure the population is systematic‑review records, not simulated datasets."
    },
    {
      "stage": "full_text_screening",
      "objective": "Confirm eligibility by detailed review of full texts.",
      "guidance": "Exclude papers lacking a human comparator or quantitative accuracy metrics. Beware studies that only report qualitative LLM performance. Note if the LLM is used for a hybrid workflow, which may render metrics incomparable."
    },
    {
      "stage": "extraction_appraisal",
      "objective": "Extract accuracy outcomes and study characteristics for meta‑analysis.",
      "guidance": "Hard‑to‑find items: confidence intervals for sensitivity/specificity, exact LLM version, and number of reviewers. Record whether screening was single‑ or dual‑reviewer. Non‑comparable studies often use different reference standards or thresholds."
    },
    {
      "stage": "synthesis_writing",
      "objective": "Summarize pooled accuracy estimates and assess heterogeneity.",
      "guidance": "Separate diagnostic‑accuracy designs from RCTs. Highlight variability due to LLM version, dataset size, or human reviewer expertise. Discuss bias from selective reporting of favorable metrics."
    },
    {
      "stage": "quality_assurance",
      "objective": "Verify that all stages meet protocol standards and data are error‑free.",
      "guidance": "Cross‑check extracted numbers against source PDFs. Ensure inclusion decisions match criteria. Confirm that JSON outputs are syntactically valid and that no duplicate records remain."
    }
  ]
}

